"use strict";(globalThis.webpackChunknotes=globalThis.webpackChunknotes||[]).push([[1378],{1797(e,a,n){n.r(a),n.d(a,{assets:()=>c,contentTitle:()=>r,default:()=>l,frontMatter:()=>t,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"payments/Sistemas de pagos de seguridad","title":"Sistemas de pagos de seguridad","description":"Fundamentos","source":"@site/docs/payments/Sistemas de pagos de seguridad.md","sourceDirName":"payments","slug":"/payments/Sistemas de pagos de seguridad","permalink":"/payments/Sistemas de pagos de seguridad","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"title":"Sistemas de pagos de seguridad","sidebar_position":1},"sidebar":"tutorialSidebar","previous":{"title":"Payments","permalink":"/payments/"},"next":{"title":"Cloud","permalink":"/cloud/"}}');var s=n(4848),o=n(8453);const t={title:"Sistemas de pagos de seguridad",sidebar_position:1},r=void 0,c={},d=[{value:"Fundamentos",id:"fundamentos",level:2}];function u(e){const a={blockquote:"blockquote",h2:"h2",p:"p",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.h2,{id:"fundamentos",children:"Fundamentos"}),"\n",(0,s.jsx)(a.p,{children:"\xbfC\xf3mo se verifica y procesa una transacci\xf3n con la terminal, por qu\xe9 el protocolo APDU no est\xe1 cifrado y qu\xe9 protege la transacci\xf3n en su lugar?"}),"\n",(0,s.jsx)(a.p,{children:"Una transacci\xf3n con una tarjeta bancaria puede ejecutarse en apenas unos segundos. Durante este intervalo de tiempo, la terminal establece una comunicaci\xf3n con la tarjeta, ejecuta una secuencia de comandos y respuestas, procesa datos de aplicaci\xf3n, realiza comprobaciones criptogr\xe1ficas y, dependiendo del flujo de autorizaci\xf3n, puede comunicarse con el adquirente y el emisor antes de decidir si la transacci\xf3n debe aprobarse o rechazarse."}),"\n",(0,s.jsx)(a.p,{children:"La comunicaci\xf3n entre una tarjeta EMV (Europay, Mastercard y Visa) y una terminal no consiste simplemente en un canal cifrado en el que toda la informaci\xf3n intercambiada permanece secreta."}),"\n",(0,s.jsx)(a.p,{children:"En el entorno de contacto o NFC, la comunicaci\xf3n se estructura mediante comandos y respuestas APDU (Application Protocol Data Unit) definidos por las especificaciones de ISO/IEC 7816 y por las especificaciones de EMV. La arquitectura utiliza autenticaci\xf3n, criptograf\xeda, llaves secretas, certificados, contadores y criptogramas para proteger determinadas decisiones y datos cr\xedticos."}),"\n",(0,s.jsx)(a.p,{children:"Poder observar una trama de APDU no significa autom\xe1ticamente poder modificar la transacci\xf3n de forma \xfatil o poder explotarla. La pregunta relevante no es \xfanicamente qu\xe9 datos pueden observarse, sino qu\xe9 componente genera cada dato, qui\xe9n puede modificarlo, qui\xe9n puede verificarlo y qu\xe9 decisi\xf3n depende de \xe9l."}),"\n",(0,s.jsx)(a.p,{children:"En una transacci\xf3n EMV, la tarjeta puede generar datos criptogr\xe1ficos utilizando llaves que no est\xe1n disponibles para la terminal. Dependiendo del flujo de la transacci\xf3n, el emisor puede posteriormente verificar un criptograma generado por la tarjeta o validar otros datos criptogr\xe1ficos asociados con la operaci\xf3n. Por eso es importante no describir EMV simplemente como un mecanismo mediante el cual \u201cla terminal verifica la tarjeta\u201d. La arquitectura distribuye las funciones de autenticaci\xf3n y autorizaci\xf3n entre la tarjeta, la terminal y los sistemas que se encuentran en el backend."}),"\n",(0,s.jsx)(a.p,{children:"La situaci\xf3n cambia cuando la terminal debe tomar determinadas decisiones sin disponer de una autorizaci\xf3n online del emisor. En esos casos, la terminal puede utilizar los mecanismos definidos por EMV para determinar si una transacci\xf3n puede continuar offline, si la terminal no cuenta con la capacidad de conectividad o si de cierta forma es forzada a estar offline. Esto no significa que la terminal est\xe9 creando una autorizaci\xf3n equivalente a la del emisor; significa que est\xe1 aplicando las reglas y los mecanismos de riesgo disponibles localmente para decidir si la operaci\xf3n puede completarse bajo esas condiciones."}),"\n",(0,s.jsxs)(a.blockquote,{children:["\n",(0,s.jsx)(a.p,{children:"La seguridad de pagos no consiste solamente en impedir que un atacante modifique un dato; consiste en controlar qu\xe9 decisiones pueden tomarse a partir de datos que no est\xe1n bajo el control de quien toma la decisi\xf3n."}),"\n"]}),"\n",(0,s.jsx)(a.p,{children:"Para analizar un sistema de pagos correctamente, conviene formular siempre las mismas preguntas: \xbfqui\xe9n genera este dato?, \xbfqui\xe9n puede modificarlo?, \xbfest\xe1 autenticado?, \xbfqui\xe9n puede verificar esa autenticidad?, \xbfqu\xe9 componente conf\xeda en \xe9l?, \xbfqu\xe9 ocurre si el dato es incorrecto?, \xbfy qu\xe9 consecuencias tiene esa decisi\xf3n para el resto del sistema? Estas preguntas son mucho m\xe1s \xfatiles para una investigaci\xf3n de seguridad que memorizar aisladamente una lista de tags EMV."})]})}function l(e={}){const{wrapper:a}={...(0,o.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},8453(e,a,n){n.d(a,{R:()=>t,x:()=>r});var i=n(6540);const s={},o=i.createContext(s);function t(e){const a=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function r(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:t(e.components),i.createElement(o.Provider,{value:a},e.children)}}}]);